import{_ as t,o as e,c as o,ae as n}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"Your First Translation Project","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/first-project.md","filePath":"get-started/first-project.md"}'),s={name:"get-started/first-project.md"};function r(i,a,l,p,c,d){return e(),o("div",null,a[0]||(a[0]=[n(`<h1 id="your-first-translation-project" tabindex="-1">Your First Translation Project <a class="header-anchor" href="#your-first-translation-project" aria-label="Permalink to &quot;Your First Translation Project&quot;">​</a></h1><p>Let&#39;s walk through creating a complete translation project from start to finish.</p><h2 id="creating-a-new-project" tabindex="-1">Creating a New Project <a class="header-anchor" href="#creating-a-new-project" aria-label="Permalink to &quot;Creating a New Project&quot;">​</a></h2><h3 id="option-1-import-a-document" tabindex="-1">Option 1: Import a Document <a class="header-anchor" href="#option-1-import-a-document" aria-label="Permalink to &quot;Option 1: Import a Document&quot;">​</a></h3><ol><li>Go to <strong>File → Import → DOCX...</strong></li><li>Select your Word document</li><li>Choose the source language (e.g., &quot;English&quot;)</li><li>Choose the target language (e.g., &quot;Dutch&quot;)</li><li>Click <strong>Import</strong></li></ol><p>Your document is now segmented and ready for translation.</p><h3 id="option-2-import-a-text-file" tabindex="-1">Option 2: Import a Text File <a class="header-anchor" href="#option-2-import-a-text-file" aria-label="Permalink to &quot;Option 2: Import a Text File&quot;">​</a></h3><ol><li>Go to <strong>File → Import → Text File...</strong></li><li>Select your <code>.txt</code> file</li><li>Each line becomes a separate segment</li></ol><h3 id="option-3-multi-file-project" tabindex="-1">Option 3: Multi-File Project <a class="header-anchor" href="#option-3-multi-file-project" aria-label="Permalink to &quot;Option 3: Multi-File Project&quot;">​</a></h3><ol><li>Go to <strong>File → Import → Folder (Multiple Files)...</strong></li><li>Select a folder containing DOCX or TXT files</li><li>Choose which files to include</li><li>All files are imported as one project</li></ol><h2 id="understanding-the-interface" tabindex="-1">Understanding the Interface <a class="header-anchor" href="#understanding-the-interface" aria-label="Permalink to &quot;Understanding the Interface&quot;">​</a></h2><p>After import, you&#39;ll see:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  📝 Project editor  │  🗂️ Project resources  │  🛠️ Tools    │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  # │ Status │ Source                │ Target                │</span></span>
<span class="line"><span>├────┼────────┼───────────────────────┼───────────────────────┤</span></span>
<span class="line"><span>│  1 │   ⬜   │ Hello, world!         │                       │</span></span>
<span class="line"><span>│  2 │   ⬜   │ This is a test.       │                       │</span></span>
<span class="line"><span>│  3 │   ⬜   │ Translate me!         │                       │</span></span>
<span class="line"><span>└────┴────────┴───────────────────────┴───────────────────────┘</span></span></code></pre></div><h3 id="status-icons" tabindex="-1">Status Icons <a class="header-anchor" href="#status-icons" aria-label="Permalink to &quot;Status Icons&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Icon</th><th>Meaning</th></tr></thead><tbody><tr><td>⬜</td><td>Not started</td></tr><tr><td>📝</td><td>Draft (edited but not confirmed)</td></tr><tr><td>✅</td><td>Confirmed</td></tr><tr><td>🔒</td><td>Locked</td></tr></tbody></table><h2 id="translating-your-first-segment" tabindex="-1">Translating Your First Segment <a class="header-anchor" href="#translating-your-first-segment" aria-label="Permalink to &quot;Translating Your First Segment&quot;">​</a></h2><ol><li>Click on segment 1&#39;s Target cell</li><li>Type your translation</li><li>Press <code>Ctrl+Enter</code> to confirm</li><li>The status changes to ✅</li></ol><h3 id="using-ai-translation" tabindex="-1">Using AI Translation <a class="header-anchor" href="#using-ai-translation" aria-label="Permalink to &quot;Using AI Translation&quot;">​</a></h3><ol><li>Click on segment 2</li><li>Press <code>Ctrl+T</code> (or use <strong>Translation → Translate Current Segment</strong>)</li><li>The AI translation appears in the Target cell</li><li>Review, edit if needed, and confirm with <code>Ctrl+Enter</code></li></ol><h2 id="setting-up-resources" tabindex="-1">Setting Up Resources <a class="header-anchor" href="#setting-up-resources" aria-label="Permalink to &quot;Setting Up Resources&quot;">​</a></h2><h3 id="add-a-translation-memory" tabindex="-1">Add a Translation Memory <a class="header-anchor" href="#add-a-translation-memory" aria-label="Permalink to &quot;Add a Translation Memory&quot;">​</a></h3><ol><li>Go to <strong>Project resources</strong> tab</li><li>Click <strong>Translation Memories</strong></li><li>Click <strong>+ Create TM</strong> or <strong>Import TMX</strong></li><li>Your TM will automatically provide matches</li></ol><h3 id="add-a-glossary" tabindex="-1">Add a Glossary <a class="header-anchor" href="#add-a-glossary" aria-label="Permalink to &quot;Add a Glossary&quot;">​</a></h3><ol><li>Go to <strong>Project resources</strong> tab</li><li>Click <strong>Glossaries</strong></li><li>Click <strong>+ Create Glossary</strong></li><li>Add terms manually or import from TSV</li></ol><h2 id="saving-your-project" tabindex="-1">Saving Your Project <a class="header-anchor" href="#saving-your-project" aria-label="Permalink to &quot;Saving Your Project&quot;">​</a></h2><ol><li>Press <code>Ctrl+S</code></li><li>Choose a name and location</li><li>Your project is saved as <code>.svproj</code></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Tip:</strong> Supervertaler auto-saves your work periodically, but it&#39;s good practice to save manually before closing.</p></div><h2 id="exporting-the-translation" tabindex="-1">Exporting the Translation <a class="header-anchor" href="#exporting-the-translation" aria-label="Permalink to &quot;Exporting the Translation&quot;">​</a></h2><p>When you&#39;re finished:</p><ol><li><p>Go to <strong>File → Export</strong></p></li><li><p>Choose your format:</p><ul><li><strong>DOCX</strong> - Standard Word document with translations</li><li><strong>Bilingual Table</strong> - Source and target side by side</li><li><strong>Text File</strong> - Plain text output</li></ul></li><li><p>Select destination and click <strong>Export</strong></p></li></ol><h2 id="project-workflow-summary" tabindex="-1">Project Workflow Summary <a class="header-anchor" href="#project-workflow-summary" aria-label="Permalink to &quot;Project Workflow Summary&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Import Document</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Set Up TMs &amp; Glossaries (optional)</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Translate Segments (manual or AI)</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Review &amp; Confirm (Ctrl+Enter)</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Save Project (.svproj)</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Export Translation</span></span></code></pre></div><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><p>Now that you&#39;ve completed your first project:</p><ul><li><a href="./../editor/keyboard-shortcuts.html">Learn keyboard shortcuts</a> for faster work</li><li><a href="./../ai-translation/batch-translation.html">Set up batch translation</a> for larger documents</li><li><a href="./../cat-tools/overview.html">Explore CAT tool workflows</a> if you use professional tools</li></ul>`,36)]))}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
